// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address depositor) public {
        address constantHard = address(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        vm.assume(depositor != constantHard);

        address stored = c.depositorAccount();

        vm.prank(stored);
        bool ok_reference;
        try c.setL1BlockValues(1, 1, 1, bytes32(0), 1, bytes32(0), 1, 1) {
            ok_reference = true;
        } catch {
            ok_reference = false;
        }

        assertTrue(ok_reference);
    }
}
